/**
 * Sheet contract drift check (P6). Parses a backend-produced snapshot
 * fixture with the Zod mirror — the same pattern as
 * `tests/report-schema.test.ts`.
 *
 * The fixture is SYNTHETIC: `backend/tests/fixtures/sheets/snapshot.synthetic.json`
 * is generated by `backend/tests/fixtures/sheets/generate_snapshot.py`,
 * which builds a sheet through the real repo and dumps the same
 * `SheetSnapshot` model the `/api/sheets/{id}/snapshot` endpoint returns.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import {
  CellResultSchema,
  PlanResultSchema,
  SheetSnapshotSchema,
} from "@/lib/schema/sheet";

const FIXTURE = join(
  import.meta.dirname,
  "..",
  "..",
  "backend",
  "tests",
  "fixtures",
  "sheets",
  "snapshot.synthetic.json",
);

const snapshotJson: unknown = JSON.parse(readFileSync(FIXTURE, "utf-8"));

describe("SheetSnapshotSchema (synthetic backend fixture)", () => {
  it("parses the backend-produced snapshot", () => {
    const parsed = SheetSnapshotSchema.safeParse(snapshotJson);
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;

    const snap = parsed.data;
    expect(snap.sheet.name).toBe("Fixture targets");
    expect(snap.rows).toHaveLength(2);
    expect(snap.columns).toHaveLength(2);
    expect(snap.cells).toHaveLength(4); // 2 rows x 2 columns
    expect(snap.latest_run?.cap).toBe(1.0);
  });

  it("carries a resolved identity through the report Field/Source mirror", () => {
    const snap = SheetSnapshotSchema.parse(snapshotJson);
    const resolved = snap.rows.find((row) => row.identity_status === "resolved");
    expect(resolved?.identity?.company_name.value).toBe("Acme Corp");
    expect(resolved?.identity?.company_name.status).toBe("verified");
    expect(
      resolved?.identity?.company_name.sources?.some((s) => s.url != null),
    ).toBe(true);
  });

  it("keeps done / unavailable / queued / blocked cell states distinct", () => {
    const snap = SheetSnapshotSchema.parse(snapshotJson);
    const byStatus = new Map(snap.cells.map((c) => [c.status, c]));
    const done = snap.cells.filter((c) => c.status === "done");
    expect(done).toHaveLength(2);
    expect(done.map((c) => c.result?.status).sort()).toEqual([
      "unavailable",
      "verified",
    ]);
    expect(byStatus.get("queued")?.result).toBeNull();
    expect(byStatus.get("blocked")?.error).toContain("Industry");
  });

  it("rejects a verified cell with no URL-bearing source (report invariant)", () => {
    const parsed = CellResultSchema.safeParse({
      value: "claims without evidence",
      status: "verified",
      sources: [{ provider: "Exa", mock: false, retrieved_at: "2026-01-01T00:00:00Z" }],
    });
    expect(parsed.success).toBe(false);
  });

  it("rejects a non-empty cell whose status is unavailable-adjacent wrong", () => {
    const parsed = CellResultSchema.safeParse({
      value: "some value",
      status: "unavailable",
    });
    // Backend allows value+unavailable? Field requires: empty → unavailable.
    // A non-empty "unavailable" is legal (reason in note). This asserts the
    // mirror accepts it — the strict half is the empty-value rule below.
    expect(parsed.success).toBe(true);
    const empty = CellResultSchema.safeParse({ value: null, status: "verified" });
    expect(empty.success).toBe(false);
  });
});

describe("PlanResultSchema (planner preview mirror)", () => {
  it("parses an add_columns preview", () => {
    const parsed = PlanResultSchema.safeParse({
      intent: "add_columns",
      columns: [
        {
          name: "Industry",
          prompt_template: "Industry of {{Company}}",
          output_type: "text",
          enum_options: [],
          source_scope: "web",
          depth: "standard",
          strategy: "research",
          depends_on: [],
        },
      ],
      question: null,
      reason: null,
      estimated_cost_usd: 0.021,
      mock: true,
    });
    expect(parsed.success).toBe(true);
  });

  it("rejects an unknown intent", () => {
    expect(
      PlanResultSchema.safeParse({ intent: "run_everything", columns: [], mock: false })
        .success,
    ).toBe(false);
  });
});
